#!/usr/bin/env bash
#
# tests/test_e2e_presign.sh — item 2: presigned URLs (query-string SigV4)
# generated by boto3, exercised with curl.
#
set -eu

ROOT=$(cd "$(dirname "$0")/.." && pwd)
PORT=${FS3_TEST_PORT:-$(( 21700 + RANDOM % 300 ))}
DATA=/tmp/fs3-ps-e2e-$$
LOG=/tmp/fs3-ps-e2e-$$.log
URL="http://127.0.0.1:$PORT"
T=/tmp/fs3-ps-$$
AK=AKIAPRESIGN00001
SK=presignSecret01234567890123456789012345678
AK2=AKIAPRESIGNADMIN
SK2=presignAdminSecret0123456789012345678901234

cleanup() {
    [ -n "${SP:-}" ] && { kill "$SP" 2>/dev/null; wait "$SP" 2>/dev/null; [ $? -ne 159 ] || echo "FAIL: server died with SIGSYS (seccomp blocked a syscall; see --seccomp=log)" >&2; } || true
    rm -rf "$DATA" "$LOG" "$T".*
}
trap cleanup EXIT

BUILD_FLAGS=""
[ "${DEBUG:-0}" = "1" ] && BUILD_FLAGS="DEBUG=1"
(cd "$ROOT" && make $BUILD_FLAGS fs3 >/dev/null 2>&1)

${FS3_WRAP:-} "$ROOT/fs3" -p "$PORT" -d "$DATA" --auth "$AK:$SK:alice" --auth "$AK2:$SK2:root" \
    --admin root --no-presign-admin --presign-max-expires 7200 >"$LOG" 2>&1 &
SP=$!
sleep 0.4
kill -0 "$SP" 2>/dev/null || { echo "server did not start" >&2; cat "$LOG" >&2; exit 1; }

export FS3_URL="$URL" FS3_AK="$AK" FS3_SK="$SK"
ps() { python3 "$ROOT/tests/presign.py" "$@"; }
code() { curl -sS -o /dev/null -w "%{http_code}" "$@"; }

PASS=0; FAIL=0
check_eq() {
    if [ "$2" = "$3" ]; then PASS=$((PASS+1)); printf '.'
    else FAIL=$((FAIL+1)); printf '\nFAIL: %s\n  want=%s\n  got =%s\n' "$1" "$3" "$2"; fi
}

python3 - <<PY
import boto3
s3 = boto3.client("s3", endpoint_url="$URL", aws_access_key_id="$AK",
                  aws_secret_access_key="$SK", region_name="us-east-1")
s3.create_bucket(Bucket="psb")
s3.put_object(Bucket="psb", Key="hello.txt", Body=b"hello presign\n")
PY

u=$(ps get psb hello.txt)
check_eq "presigned GET" "$(curl -sS "$u")" "hello presign"
check_eq "presigned GET with Range" "$(curl -sS -H 'Range: bytes=0-4' "$u")" "hello"
check_eq "presigned HEAD" "$(code -I "$(ps head psb hello.txt)")" "200"

printf 'uploaded via presigned PUT' > "$T.up"
u=$(ps put psb up.txt)
check_eq "presigned PUT" "$(code -T "$T.up" "$u")" "200"
check_eq "presigned PUT stored" "$(curl -sS "$(ps get psb up.txt)")" "uploaded via presigned PUT"

# A presigned GET URL can't be used for another method or key.
u=$(ps get psb hello.txt)
check_eq "GET URL used for PUT → 403" "$(code -T "$T.up" "$u")" "403"
tampered=$(echo "$u" | sed 's#/psb/hello.txt#/psb/up.txt#')
check_eq "tampered key path → 403" "$(code "$tampered")" "403"
tampered=$(echo "$u" | sed 's#X-Amz-Expires=3600#X-Amz-Expires=3500#')
check_eq "tampered X-Amz-Expires → 403" "$(code "$tampered")" "403"
check_eq "unsigned x-amz-* header added → 403" \
    "$(code -H 'x-amz-copy-source: /psb/up.txt' "$u")" "403"
check_eq "Authorization + presign → 400" \
    "$(code -H 'Authorization: AWS4-HMAC-SHA256 x' "$u")" "400"
check_eq "duplicate X-Amz-Signature → 400" "$(code "$u&X-Amz-Signature=00")" "400"
check_eq "STS token → 501" "$(code "$u&X-Amz-Security-Token=abc")" "501"

# Expiry.
u=$(ps get psb hello.txt 1)
sleep 2.2
check_eq "expired URL → 403" "$(code "$u")" "403"
case "$(curl -sS "$u")" in *"Request has expired"*) ok=yes ;; *) ok=no ;; esac
check_eq "expired message" "$ok" "yes"
check_eq "expires > --presign-max-expires → 400" "$(code "$(ps get psb hello.txt 7201)")" "400"
check_eq "expires = max ok" "$(code "$(ps get psb hello.txt 7200)")" "200"

# Keys needing canonical-URI encoding.
for k in "with space.txt" "ünïcødé/ключ.txt" "plus+and&amp=.txt" "a/b/c%2Fd"; do
    python3 - "$k" <<PY
import boto3, sys
s3 = boto3.client("s3", endpoint_url="$URL", aws_access_key_id="$AK",
                  aws_secret_access_key="$SK", region_name="us-east-1")
s3.put_object(Bucket="psb", Key=sys.argv[1], Body=b"odd key")
PY
    check_eq "presigned GET '$k'" "$(curl -sS "$(ps get psb "$k")")" "odd key"
done

# Presigned DELETE.
check_eq "presigned DELETE" "$(code -X DELETE "$(ps delete psb up.txt)")" "204"

# Cross-user: presigning doesn't extend the signer's rights.
FS3_AK=$AK2 FS3_SK=$SK2 python3 - <<PY
import boto3
s3 = boto3.client("s3", endpoint_url="$URL", aws_access_key_id="$AK2",
                  aws_secret_access_key="$SK2", region_name="us-east-1")
s3.create_bucket(Bucket="rootb")
s3.put_object(Bucket="rootb", Key="secret", Body=b"s")
PY
check_eq "alice presign on root's bucket → 403" "$(code "$(ps get rootb secret)")" "403"
# --no-presign-admin: admin keys can't mint bearer URLs.
check_eq "admin presign refused" \
    "$(code "$(FS3_AK=$AK2 FS3_SK=$SK2 python3 "$ROOT/tests/presign.py" get rootb secret)")" "403"

echo
echo "===== presign e2e: $PASS passed, $FAIL failed ====="
[ "$FAIL" -eq 0 ]
